adepto:{n:"Spirit Adept",e:"Ambition",b:["Meditation","Summon a <b>Pashey</b> 1/2 or a <b>Straxiart</b> 2/1. Your hero gains +1 Attack this turn. Your <b>Focus</b> starts from the 2nd Emotion slot."],m:["Spirit Echo","Summon a <b>Pashey</b> 1/2 (<b>Legacy</b>: from now on your Spirits gain +0/+1) or a <b>Straxiart</b> 2/1 (<b>Legacy</b>: from now on your Spirits gain +1/+0). The bonus is permanent and stacks."]},
traccia:{n:"Pathtracker",e:"Fear",b:["Bait","The next card you play takes 2 slots but has <b>Legacy</b>: <b>Ransom</b> 1 on your next turn. When your hero Mutates, it gains <b>Escape Route</b>: the first time it would drop to 0 HP, it stays at 1 HP."],m:["Escape Bait","Like <b>Bait</b>, and the card also has <b>Escape Route</b>."]},
incisore:{n:"Arcane Engraver",e:"Wonder",b:["Engraving","<b>Graft</b> a minor <b>runic Prosthesis</b> (+1/+1)."],m:["Transplant","Move a <b>Prosthesis</b> from one minion to another; the one receiving it gains +1/+1 and can <b>Mutate</b>."]},
scudiera:{n:"Magga Squire",e:"Right",b:["Scale Rite","An allied minion gains <b>Scale</b> 3. Every 4 uses of the hero power, your hero gains <b>Scale</b> 4."],m:["Blood Rite","An allied minion gains <b>Scale</b> 2 and <b>Bloodletting</b>, but the Bloodletting heals your hero instead of the minion. Every 4 uses of the hero power, your hero gains <b>Scale</b> 4."]}
